from pathlib import Path
import sys

p = Path(sys.argv[1])
s = p.read_text()

def rep(old, new, count=None):
    global s
    if old not in s:
        raise SystemExit(f'missing patch anchor: {old[:80]!r}')
    s = s.replace(old, new, -1 if count is None else count)

rep('import androidx.compose.foundation.ExperimentalFoundationApi\n', 'import androidx.compose.foundation.ExperimentalFoundationApi\nimport androidx.compose.foundation.gestures.detectDragGesturesAfterLongPress\n', 1)
rep('import androidx.compose.material3.Scaffold\n', 'import androidx.compose.material3.Scaffold\nimport androidx.compose.material3.SmallFloatingActionButton\n', 1)
rep('import androidx.compose.runtime.LaunchedEffect\n', 'import androidx.compose.runtime.LaunchedEffect\nimport androidx.compose.runtime.mutableFloatStateOf\n', 1)
rep('import androidx.compose.ui.draw.clip\n', 'import androidx.compose.ui.draw.clip\nimport androidx.compose.ui.graphics.graphicsLayer\n', 1)
rep('import androidx.compose.ui.platform.LocalLayoutDirection\n', 'import androidx.compose.ui.platform.LocalLayoutDirection\nimport androidx.compose.ui.platform.LocalDensity\nimport androidx.compose.ui.platform.LocalHapticFeedback\n', 1)
rep('import androidx.compose.ui.text.font.FontWeight\n', 'import androidx.compose.ui.text.font.FontWeight\nimport androidx.compose.ui.hapticfeedback.HapticFeedbackType\nimport androidx.compose.ui.input.pointer.pointerInput\n', 1)
rep('import java.util.Locale\n', 'import java.util.Locale\nimport java.time.LocalDateTime\nimport java.time.format.DateTimeFormatter\nimport kotlinx.coroutines.delay\nimport kotlin.math.abs\nimport ir.appdeck.launcher.util.PersianDate\nimport ir.appdeck.launcher.util.fullPersianText\nimport ir.appdeck.launcher.util.toPersianDigits\n', 1)

rep('''        Scaffold(\n            modifier = Modifier.fillMaxSize(),\n            bottomBar = {''', '''        Scaffold(\n            modifier = Modifier.fillMaxSize(),\n            floatingActionButton = {\n                if (tab == RootTab.DASHBOARD) {\n                    SmallFloatingActionButton(\n                        onClick = { showAddSection = true },\n                        containerColor = MaterialTheme.colorScheme.primary,\n                        contentColor = Color.White\n                    ) {\n                        Icon(Icons.Default.Add, contentDescription = "ساخت بخش جدید")\n                    }\n                }\n            },\n            bottomBar = {''', 1)

rep('''                    onDeleteClick = { deleteSection = section },\n                    onToggleCollapsed = { onToggleCollapsed(section.id) },\n                    onEditApp = { pkg -> editApp = section to pkg }\n                )''', '''                    onDeleteClick = { deleteSection = section },\n                    onToggleCollapsed = { onToggleCollapsed(section.id) },\n                    onEditApp = { pkg -> editApp = section to pkg },\n                    onMovePackage = { pkg, direction -> onMovePackage(section.id, pkg, direction) }\n                )''', 1)

rep('''    var editApp by remember { mutableStateOf<Pair<AppSection, String>?>(null) }\n    var searchOpen by remember { mutableStateOf(false) }\n    var query by remember { mutableStateOf("") }\n\n    val appMap = remember(installedApps) { installedApps.associateBy { it.packageName } }\n    val normalizedQuery = remember(query) { normalizeSearch(query) }\n    val visibleSections = remember(sections, appMap, normalizedQuery) {\n        if (normalizedQuery.isBlank()) sections else sections.mapNotNull { section ->\n            val titleMatches = normalizeSearch(section.title).contains(normalizedQuery)\n            val matchingPackages = section.packages.filter { pkg ->\n                val app = appMap[pkg]\n                val alias = section.aliases[pkg].orEmpty()\n                normalizeSearch(alias).contains(normalizedQuery) ||\n                    app?.searchText?.contains(normalizedQuery) == true ||\n                    normalizeSearch(pkg).contains(normalizedQuery)\n            }\n            when {\n                titleMatches -> section\n                matchingPackages.isNotEmpty() -> section.copy(packages = matchingPackages, collapsed = false)\n                else -> null\n            }\n        }\n    }''', '''    var editApp by remember { mutableStateOf<Pair<AppSection, String>?>(null) }\n\n    val appMap = remember(installedApps) { installedApps.associateBy { it.packageName } }\n    val visibleSections = sections''', 1)

rep('''        item(key = "top") {\n            DashboardTopBar(\n                title = dashboardTitle,\n                searchOpen = searchOpen,\n                query = query,\n                onQueryChange = { query = it },\n                onSearchToggle = {\n                    searchOpen = !searchOpen\n                    if (!searchOpen) query = ""\n                },\n                onAddSection = onAddSection\n            )\n        }''', '''        item(key = "top") {\n            CompactDateTimeHeader()\n        }''', 1)

rep('''        } else if (visibleSections.isEmpty()) {\n            item(key = "no-search") {\n                Surface(\n                    shape = RoundedCornerShape(22.dp),\n                    color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.55f),\n                    modifier = Modifier.fillMaxWidth()\n                ) {\n                    Text(\n                        "برنامه یا بخشی با این عبارت پیدا نشد.",\n                        modifier = Modifier.padding(22.dp),\n                        textAlign = TextAlign.Center,\n                        color = MaterialTheme.colorScheme.onSurfaceVariant\n                    )\n                }\n            }\n        } else {''', '} else {', 1)

anchor = '''    onDeleteClick: () -> Unit,\n    onToggleCollapsed: () -> Unit,\n    onEditApp: (String) -> Unit\n) {'''
pos = s.index('private fun SectionCard')
patch_pos = s.index(anchor, pos)
s = s[:patch_pos] + s[patch_pos:].replace(anchor, '''    onDeleteClick: () -> Unit,\n    onToggleCollapsed: () -> Unit,\n    onEditApp: (String) -> Unit,\n    onMovePackage: (String, Int) -> Unit\n) {''', 1)

rep('''                        columns = gridColumns,\n                        showLabels = showLabels,\n                        onEditApp = onEditApp\n                    )''', '''                        columns = gridColumns,\n                        showLabels = showLabels,\n                        onEditApp = onEditApp,\n                        onMovePackage = onMovePackage\n                    )''', 1)

rep('''private fun AppGrid(\n    section: AppSection,\n    appMap: Map<String, InstalledApp>,\n    columns: Int,\n    showLabels: Boolean,\n    onEditApp: (String) -> Unit\n) {''', '''private fun AppGrid(\n    section: AppSection,\n    appMap: Map<String, InstalledApp>,\n    columns: Int,\n    showLabels: Boolean,\n    onEditApp: (String) -> Unit,\n    onMovePackage: (String, Int) -> Unit\n) {''', 1)

rep('''                            packageName = pkg,\n                            label = label,\n                            showLabel = showLabels,\n                            onLongClick = { onEditApp(pkg) }\n                        )''', '''                            packageName = pkg,\n                            label = label,\n                            showLabel = showLabels,\n                            columns = safeColumns,\n                            onMove = { direction -> onMovePackage(pkg, direction) }\n                        )''', 1)

start = s.index('@Composable\nprivate fun AppTile(')
end = s.index('@Composable\nprivate fun CachedAppIcon', start)
new_tile = '''@Composable\nprivate fun AppTile(\n    packageName: String,\n    label: String,\n    showLabel: Boolean,\n    columns: Int,\n    onMove: (Int) -> Unit\n) {\n    val context = LocalContext.current\n    val density = LocalDensity.current\n    val haptic = LocalHapticFeedback.current\n    val tileTint = remember(packageName) { appAccent(packageName) }\n    var dragX by remember(packageName) { mutableFloatStateOf(0f) }\n    var dragY by remember(packageName) { mutableFloatStateOf(0f) }\n    var dragging by remember(packageName) { mutableStateOf(false) }\n    val thresholdPx = with(density) { 34.dp.toPx() }\n\n    Column(\n        modifier = Modifier\n            .graphicsLayer {\n                translationX = dragX.coerceIn(-thresholdPx, thresholdPx)\n                translationY = dragY.coerceIn(-thresholdPx, thresholdPx)\n                scaleX = if (dragging) 1.06f else 1f\n                scaleY = if (dragging) 1.06f else 1f\n                alpha = if (dragging) 0.92f else 1f\n            }\n            .clip(RoundedCornerShape(15.dp))\n            .pointerInput(packageName, columns) {\n                detectDragGesturesAfterLongPress(\n                    onDragStart = {\n                        dragging = true\n                        haptic.performHapticFeedback(HapticFeedbackType.LongPress)\n                    },\n                    onDragCancel = { dragX = 0f; dragY = 0f; dragging = false },\n                    onDragEnd = { dragX = 0f; dragY = 0f; dragging = false },\n                    onDrag = { change, amount ->\n                        change.consume()\n                        dragX += amount.x\n                        dragY += amount.y\n                        if (abs(dragX) >= thresholdPx) {\n                            onMove(if (dragX < 0f) 1 else -1)\n                            dragX = 0f\n                        }\n                        if (abs(dragY) >= thresholdPx) {\n                            onMove(if (dragY > 0f) columns else -columns)\n                            dragY = 0f\n                        }\n                    }\n                )\n            }\n            .combinedClickable(onClick = { launchPackage(context, packageName) })\n            .padding(horizontal = 2.dp, vertical = 6.dp),\n        horizontalAlignment = Alignment.CenterHorizontally\n    ) {\n        Surface(\n            shape = RoundedCornerShape(16.dp),\n            color = tileTint.copy(alpha = if (dragging) 0.16f else 0.09f),\n            border = BorderStroke(1.dp, tileTint.copy(alpha = if (dragging) 0.38f else 0.17f)),\n            shadowElevation = if (dragging) 7.dp else 1.dp\n        ) {\n            CachedAppIcon(\n                packageName = packageName,\n                label = label,\n                modifier = Modifier.padding(6.dp),\n                sizeDp = 42\n            )\n        }\n        if (showLabel) {\n            Spacer(Modifier.height(5.dp))\n            Text(\n                label,\n                maxLines = 1,\n                overflow = TextOverflow.Ellipsis,\n                fontSize = 10.sp,\n                textAlign = TextAlign.Center,\n                modifier = Modifier.fillMaxWidth()\n            )\n        }\n    }\n}\n\n'''
s = s[:start] + new_tile + s[end:]

marker = '@Composable\nprivate fun DashboardTopBar('
pos = s.index(marker)
compact = '''@Composable\nprivate fun CompactDateTimeHeader() {\n    var now by remember { mutableStateOf(LocalDateTime.now()) }\n    LaunchedEffect(Unit) {\n        while (true) {\n            now = LocalDateTime.now()\n            delay((60 - now.second).coerceAtLeast(1) * 1_000L)\n        }\n    }\n    val jalali = remember(now.toLocalDate()) { PersianDate.fromGregorian(now.toLocalDate()) }\n    val dateText = remember(jalali, now.toLocalDate()) { jalali.fullPersianText(now.toLocalDate()) }\n    val timeText = remember(now.hour, now.minute) {\n        now.format(DateTimeFormatter.ofPattern("HH:mm")).toPersianDigits()\n    }\n    Text(\n        text = "$dateText  •  $timeText",\n        modifier = Modifier.fillMaxWidth().padding(vertical = 1.dp),\n        textAlign = TextAlign.Center,\n        color = MaterialTheme.colorScheme.onSurfaceVariant,\n        fontSize = 11.sp,\n        fontWeight = FontWeight.Medium,\n        maxLines = 1,\n        overflow = TextOverflow.Ellipsis\n    )\n}\n\n'''
s = s[:pos] + compact + s[pos:]

s = s.replace('    var titleDraft by remember(dashboardTitle) { mutableStateOf(dashboardTitle) }\n\n', '')
settings_card = '        item(key = "dashboard-name") {'
if settings_card in s:
    st = s.index(settings_card)
    en = s.index('        item(key = "layout") {', st)
    s = s[:st] + s[en:]

s = s.replace('"شخصی‌سازی ظاهر و چیدمان بدون سنگین کردن برنامه",', '"ظاهر، چیدمان و جابه‌جایی لمسی برنامه‌ها",', 1)
rep('''                        Text("چیدمان برنامه‌ها", fontWeight = FontWeight.ExtraBold, fontSize = 17.sp)\n                    }''', '''                        Text("چیدمان برنامه‌ها", fontWeight = FontWeight.ExtraBold, fontSize = 17.sp)\n                    }\n                    Text(\n                        "برای جابه‌جایی، آیکون برنامه را کمی نگه‌دار و به جای جدید بکش.",\n                        color = MaterialTheme.colorScheme.onSurfaceVariant,\n                        fontSize = 11.sp\n                    )''', 1)

p.write_text(s)
print('AppDeck V5 UI patch applied')
